def t(f, a) { try { f(a) } catch e { print(e) } }
t(read, "missing.txt")
t(listdir, "nodir")
t(remove, "nope")
try { write("nodir/a", "x") } catch e { print(e) }
try { append("nodir/a", "x") } catch e { print(e) }
read("last.txt")

mkdir("d")
write("f", "x")
try { read("d") } catch e { print(e) }
try { write("d", "x") } catch e { print(e) }
try { append("d", "x") } catch e { print(e) }
try { delete("d") } catch e { print(e) }
try { listdir("f") } catch e { print(e) }

mkdir("d")
write("d/x", "1")
write("f", "x")
try { remove("d") } catch e { print(e[:24]) }
try { rename("nope", "x") } catch e { print(e[:19]) }
try { copy("nope", "x") } catch e { print(e[:17]) }
try { mkdir("f") } catch e { print(e[:17]) }

print(type(cwd()), len(cwd()) > 0, exists(cwd()), abspath(".") == cwd())
print(dirname("a/b/c.txt"), "[" + dirname("c.txt") + "]", type(abspath("x")))
try { dirname(5) } catch e { print(e) }

try { format_time("a", "%Y") } catch e { print(e) }
try { format_time(1, 5) } catch e { print(e) }
try { format_time(num("1" + "0" * 30), "%Y") } catch e { print(e[:24]) }

let r = random()
print(r >= 0, r < 1, type(r))
let ok = true
for i = 1 to 200 { let x = random()
if x < 0 or x >= 1 { ok = false } }
print(ok)

let seen = {}
for i = 1 to 400 { seen[str(randint(1, 3))] = true }
print(sorted(keys(seen)), randint(7, 7), type(randint(1, 2)), randint(-2, -2))
let ok = true
for i = 1 to 300 { let n = randint(-5, 5)
if n < -5 or n > 5 { ok = false } }
print(ok)

try { randint(5, 3) } catch e { print(e) }
try { randint(1.5, 3) } catch e { print(e) }
try { randint("a", 3) } catch e { print(e) }
try { randint(1) } catch e { print(e) }

let l = [1, 2, 3]
print(choice(l) in l, choice(["x"]), l)
let seen = {}
for i = 1 to 300 { seen[choice(["a", "b"])] = true }
print(sorted(keys(seen)))
try { choice([]) } catch e { print(e) }
try { choice(5) } catch e { print(e) }

def stop(n) { for i = 1 to 10 { if i == n { exit(n) } print(i) } }
stop(3)
print("never")

try { exit("a") } catch e { print(e) }
try { exit(1.5) } catch e { print(e) }
try { exit(true) } catch e { print(e) }
try { exit(1, 2) } catch e { print(e) }
print("still here")

